import logging
from typing import Optional
from .parsers import SpecParser
from .templates import DiagramTemplates

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("DiagramSkill")

class DiagramEngine:
    """Core engine to transform specifications into Mermaid diagrams."""
    
    def __init__(self):
        self.parser = SpecParser()
        self.templates = DiagramTemplates()

    def generate(self, specification: str) -> str:
        try:
            logger.info("Initiating diagram synthesis...")
            
            # 1. Determine Diagram Type
            diag_type = self.parser.determine_diagram_type(specification)
            logger.info(f"Detected diagram type: {diag_type}")
            
            # 2. Extract Relationships
            triplets = self.parser.extract_triplets(specification)
            if not triplets:
                logger.warning("No clear relationships found. Defaulting to basic flowchart.")
            
            # 3. Build DSL
            output = self._build_dsl(diag_type, triplets)
            
            return f"```mermaid\n{output}\n```"
            
        except Exception as e:
            logger.error(f"Synthesis failed: {str(e)}")
            return "Error generating diagram: Specification too ambiguous."

    def _build_dsl(self, diag_type: str, triplets: list) -> str:
        if diag_type == "sequence":
            header = self.templates.SEQUENCE
            body = "\n".join([f"    {s}->>{o}: {a}" for s, a, o in triplets])
        elif diag_type == "erd":
            header = self.templates.ERD
            body = "\n".join([f"    {s} ||--o{{ {o} : \"{a}\"" for s, a, o in triplets])
        elif diag_type == "class":
            header = self.templates.CLASS
            body = "\n".join([f"    {s} <|-- {o}" for s, a, o in triplets])
        else: # Default Flowchart
            header = self.templates.FLOWCHART
            body = "\n".join([f"    {s} --> {o}" for s, a, o in triplets])
            
        return header + body

